for p in sorted(files):
    txt = extract(p)
    sc = score(txt)
    best = max(sc, key=sc.get)
    if sc[best] == 0:
        best = 'music_history'

    dest = ROOT / best / p.name
    if dest.exists():
        raise SystemExit(f'Collision: {dest} already exists')

    shutil.move(str(p)

